  1→// license:GPL2+
  2→// copyright-holders:Felipe Sanches
  3→/***************************************************************************
  4→
  5→	KN5000 control panel HLE
  6→
  7→	Emulates the two Mitsubishi M37471M2196S MCUs on the control panel.
  8→	Since no ROM dumps are available, this uses High Level Emulation based
  9→	on reverse engineering of the main CPU firmware protocol.
 10→
 11→	Protocol documentation: https://felipesanches.github.io/kn5000-docs/control-panel-protocol/
 12→
 13→***************************************************************************/
 14→
 15→#ifndef MAME_MATSUSHITA_KN5000_CPANEL_H
 16→#define MAME_MATSUSHITA_KN5000_CPANEL_H
 17→
 18→#pragma once
 19→
 20→#include <queue>
 21→
 22→class kn5000_cpanel_device :
 23→	public device_t
 24→{
 25→public:
 26→	kn5000_cpanel_device(const machine_config &mconfig, const char *tag, device_t *owner, uint32_t clock = 0);
 27→
 28→	// Serial interface from main CPU
 29→	void rxd(int state);
 30→	void sioclk(int state);
 31→	void tx_start(int state);  // Called when CPU starts a new byte transmission
 32→
 33→	// Callbacks to main CPU
 34→	auto txd() { return m_txd_cb.bind(); }
 35→	auto sclk_out() { return m_sclk_out_cb.bind(); }
 36→
 37→	// Configuration
 38→	void set_baudrate(uint16_t br);
 39→
 40→	// Button input port setters (called from main driver)
 41→	void set_cpl_port(int n, ioport_port *port) { m_cpl_ports[n] = port; }
 42→	void set_cpr_port(int n, ioport_port *port) { m_cpr_ports[n] = port; }
 43→
 44→protected:
 45→	// device_t overrides
 46→	virtual void device_start() override ATTR_COLD;
 47→	virtual void device_reset() override ATTR_COLD;
 48→
 49→	TIMER_CALLBACK_MEMBER(timer_callback);
 50→
 51→private:
 52→	// Serial communication
 53→	void send_byte(uint8_t data);
 54→	void process_received_byte(uint8_t data);
 55→	void process_command();
 56→
 57→	// Response generation
 58→	void send_sync_packet();
 59→	void send_button_packet(int segment, bool is_left_panel);
 60→	void send_all_button_states(bool is_left_panel);
 61→
 62→	// LED control
 63→	void process_led_command(uint8_t row, uint8_t data);
 64→
 65→	// Read button state from input ports
 66→	uint8_t read_button_segment(int segment, bool is_left_panel);
 67→
 68→	// Timer
 69→	emu_timer *m_timer;
 70→	uint16_t m_baud_rate;
 71→
 72→	// Serial RX state
 73→	uint8_t m_rx_clock_count;
 74→	uint8_t m_rx_shift_register;
 75→	uint8_t m_rxd;
 76→	uint8_t m_sioclk_state;
 77→
 78→	// Serial TX state
 79→	uint8_t m_tx_clock_count;
 80→	uint8_t m_tx_shift_register;
 81→	std::queue<uint8_t> m_tx_queue;
 82→	bool m_tx_skip_first_falling;  // Skip first falling edge after pre-outputting bit 0
 83→
 84→	// Command buffer (2-byte commands)
 85→	uint8_t m_cmd_buffer[2];
 86→	uint8_t m_cmd_index;
 87→
 88→	// Protocol state
 89→	bool m_initialized;
 90→	uint8_t m_last_button_state[22];  // 11 segments * 2 panels
 91→
 92→	// Callbacks
 93→	devcb_write_line m_txd_cb;
 94→	devcb_write_line m_sclk_out_cb;
 95→
 96→	// Input port pointers (set by main driver)
 97→	ioport_port *m_cpl_ports[11];  // Left panel segments 0-10
 98→	ioport_port *m_cpr_ports[11];  // Right panel segments 0-10
 99→
100→	// LED outputs
101→	output_finder<50> m_cpl_leds;  // Left panel LEDs (CPL_0 through CPL_49)
102→	output_finder<69> m_cpr_leds;  // Right panel LEDs (CPR_0 through CPR_68)
103→};
104→
105→DECLARE_DEVICE_TYPE(KN5000_CPANEL, kn5000_cpanel_device)
106→
107→#endif // MAME_MATSUSHITA_KN5000_CPANEL_H
108→

  1→// license:GPL2+
  2→// copyright-holders:Felipe Sanches
  3→/***************************************************************************
  4→
  5→	KN5000 control panel HLE
  6→
  7→	Emulates the two Mitsubishi M37471M2196S MCUs on the control panel.
  8→
  9→	Protocol Summary:
 10→	-----------------
 11→	- Commands are 2-byte sequences from main CPU
 12→	- Bits 7-5 of command byte select panel (0-3=left, 4-7=right)
 13→	- Response packets have type encoded in bits 5-3:
 14→	    Type 0,1: Button state (bit 6 selects panel: 0=right, 1=left)
 15→	    Type 2: Encoder delta
 16→	    Type 3-5: Sync/ACK
 17→	    Type 6,7: Multi-byte data
 18→
 19→	See: https://felipesanches.github.io/kn5000-docs/control-panel-protocol/
 20→
 21→***************************************************************************/
 22→
 23→#include "emu.h"
 24→#include "kn5000_cpanel.h"
 25→
 26→#define LOG_COMMANDS (1U << 1)
 27→#define LOG_SERIAL   (1U << 2)
 28→#define LOG_BUTTONS  (1U << 3)
 29→#define LOG_LEDS     (1U << 4)
 30→
 31→#define VERBOSE (LOG_COMMANDS | LOG_SERIAL)
 32→#include "logmacro.h"
 33→
 34→DEFINE_DEVICE_TYPE(KN5000_CPANEL, kn5000_cpanel_device, "kn5000_cpanel", "KN5000 Control Panel HLE")
 35→
 36→kn5000_cpanel_device::kn5000_cpanel_device(const machine_config &mconfig, const char *tag, device_t *owner, uint32_t clock) :
 37→	device_t(mconfig, KN5000_CPANEL, tag, owner, clock),
 38→	m_timer(nullptr),
 39→	m_baud_rate(0),
 40→	m_rx_clock_count(8),
 41→	m_rx_shift_register(0),
 42→	m_rxd(1),
 43→	m_sioclk_state(0),
 44→	m_tx_clock_count(0),
 45→	m_tx_shift_register(0xff),
 46→	m_tx_skip_first_falling(false),
 47→	m_cmd_index(0),
 48→	m_initialized(false),
 49→	m_txd_cb(*this),
 50→	m_sclk_out_cb(*this),
 51→	m_cpl_leds(*this, "cpl_led_%u", 0U),
 52→	m_cpr_leds(*this, "cpr_led_%u", 0U)
 53→{
 54→	std::fill(std::begin(m_cmd_buffer), std::end(m_cmd_buffer), 0);
 55→	std::fill(std::begin(m_last_button_state), std::end(m_last_button_state), 0);
 56→	std::fill(std::begin(m_cpl_ports), std::end(m_cpl_ports), nullptr);
 57→	std::fill(std::begin(m_cpr_ports), std::end(m_cpr_ports), nullptr);
 58→}
 59→
 60→void kn5000_cpanel_device::device_start()
 61→{
 62→	m_timer = timer_alloc(FUNC(kn5000_cpanel_device::timer_callback), this);
 63→
 64→	// Resolve LED outputs
 65→	m_cpl_leds.resolve();
 66→	m_cpr_leds.resolve();
 67→
 68→	// Save state
 69→	save_item(NAME(m_baud_rate));
 70→	save_item(NAME(m_rx_clock_count));
 71→	save_item(NAME(m_rx_shift_register));
 72→	save_item(NAME(m_rxd));
 73→	save_item(NAME(m_sioclk_state));
 74→	save_item(NAME(m_tx_clock_count));
 75→	save_item(NAME(m_tx_shift_register));
 76→	save_item(NAME(m_tx_skip_first_falling));
 77→	save_item(NAME(m_cmd_buffer));
 78→	save_item(NAME(m_cmd_index));
 79→	save_item(NAME(m_initialized));
 80→	save_item(NAME(m_last_button_state));
 81→
 82→	// Initial state - line idle high
 83→	m_txd_cb(1);
 84→}
 85→
 86→void kn5000_cpanel_device::device_reset()
 87→{
 88→	m_baud_rate = 0;
 89→	m_rx_clock_count = 8;
 90→	m_tx_clock_count = 0;
 91→	m_tx_skip_first_falling = false;
 92→	m_cmd_index = 0;
 93→	m_initialized = false;
 94→
 95→	// Clear TX queue
 96→	while (!m_tx_queue.empty())
 97→		m_tx_queue.pop();
 98→
 99→	std::fill(std::begin(m_last_button_state), std::end(m_last_button_state), 0);
100→}
101→
102→void kn5000_cpanel_device::set_baudrate(uint16_t br)
103→{
104→	m_baud_rate = br;
105→	LOGMASKED(LOG_SERIAL, "Baud rate set to %d\n", br);
106→
107→	if (br)
108→	{
109→		m_timer->adjust(attotime::from_hz(m_baud_rate), 0, attotime::from_hz(m_baud_rate));
110→	}
111→	else
112→	{
113→		m_timer->reset(attotime::never);
114→	}
115→}
116→
117→void kn5000_cpanel_device::rxd(int state)
118→{
119→	m_rxd = state;
120→}
121→
122→void kn5000_cpanel_device::tx_start(int state)
123→{
124→	// Called when CPU starts transmitting a new byte - reset RX to sync byte boundaries
125→	if (state)
126→	{
127→		LOGMASKED(LOG_SERIAL, "cpanel tx_start: resetting RX counter for sync\n");
128→		m_rx_clock_count = 8;
129→		m_rx_shift_register = 0;
130→	}
131→}
132→
133→void kn5000_cpanel_device::sioclk(int state)
134→{
135→	if (m_sioclk_state == state)
136→		return;
137→
138→	m_sioclk_state = state;
139→
140→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
141→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
142→
143→	if (state)
144→	{
145→		// Rising edge: Sample RXD (receive bit from CPU)
146→		if (m_rx_clock_count > 0)
147→		{
148→			m_rx_shift_register >>= 1;
149→			m_rx_shift_register |= (m_rxd << 7);
150→			m_rx_clock_count--;
151→
152→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
153→				m_rxd, m_rx_shift_register, m_rx_clock_count);
154→
155→			if (m_rx_clock_count == 0)
156→			{
157→				// Full byte received
158→				m_rx_clock_count = 8;
159→				process_received_byte(m_rx_shift_register);
160→			}
161→		}
162→	}
163→	else
164→	{
165→		// Falling edge: Output TXD (transmit bit to CPU)
166→		// This prepares the bit for the CPU to sample on the next rising edge
167→		if (m_tx_skip_first_falling)
168→		{
169→			// Skip this falling edge - bit 0 was pre-output and we need to give
170→			// CPU a rising edge to sample it before we output bit 1
171→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
172→			m_tx_skip_first_falling = false;
173→		}
174→		else if (m_tx_clock_count > 0)
175→		{
176→			if (m_tx_clock_count == 8)
177→			{
178→				// First bit of a chained byte (loaded from queue) — output bit 0 without shifting
179→				LOGMASKED(LOG_SERIAL, "cpanel TX bit 0 (chained): %d, shift_reg=%02X\n",
180→					m_tx_shift_register & 1, m_tx_shift_register);
181→				m_txd_cb(m_tx_shift_register & 1);
182→				m_tx_clock_count--;
183→			}
184→			else
185→			{
186→				// Normal operation: shift out the next bit
187→				m_tx_shift_register >>= 1;
188→				LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
189→					m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
190→				m_txd_cb(m_tx_shift_register & 1);
191→				m_tx_clock_count--;
192→			}
193→
194→			if (m_tx_clock_count == 0)
195→			{
196→				// Byte sent, check for more
197→				if (!m_tx_queue.empty())
198→				{
199→					m_tx_shift_register = m_tx_queue.front();
200→					m_tx_queue.pop();
201→					m_tx_clock_count = 8;  // Full 8 bits — don't pre-output yet
202→
203→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte queued: %02X (no pre-output)\n",
204→						m_tx_shift_register);
205→
206→					// Don't pre-output: bit 7 of previous byte is still on the line
207→					// and needs to be sampled by CPU on the next rising edge.
208→					// Bit 0 of new byte will be output on the next falling edge.
209→				}
210→				else
211→				{
212→					// Transmission complete — leave the last bit on the line.
213→					// Do NOT call m_txd_cb(1) here: that would overwrite bit 7
214→					// of the last byte before the CPU samples it on the next
215→					// rising edge. The line will be updated when send_byte()
216→					// pre-outputs the next byte's bit 0.
217→					LOGMASKED(LOG_SERIAL, "cpanel TX done, holding last bit\n");
218→				}
219→			}
220→		}
221→	}
222→}
223→
224→void kn5000_cpanel_device::send_byte(uint8_t data)
225→{
226→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
227→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
228→
229→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
230→	{
231→		// Start sending immediately
232→		m_tx_shift_register = data;
233→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
234→
235→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
236→		m_txd_cb(m_tx_shift_register & 1);
237→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
238→			data, data & 1);
239→
240→		// Only skip the first falling edge if clock is currently HIGH.
241→		// If clock is HIGH: next edge = falling (skip it)
242→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
243→		m_tx_skip_first_falling = (m_sioclk_state == 1);
244→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
245→	}
246→	else
247→	{
248→		// Queue for later
249→		m_tx_queue.push(data);
250→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
251→	}
252→}
253→
254→void kn5000_cpanel_device::process_received_byte(uint8_t data)
255→{
256→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
257→
258→	// Ignore 0xFF when it appears as a command byte (first byte of pair).
259→	// In synchronous serial mode, the CPU must send dummy bytes to clock in
260→	// response data. These dummy 0xFF bytes are not valid commands — without
261→	// this filter they would be paired with the next real command byte,
262→	// misaligning the 2-byte command parser and potentially triggering
263→	// unintended LED commands or sync responses.
264→	if (m_cmd_index == 0 && data == 0xFF)
265→	{
266→		LOGMASKED(LOG_SERIAL, "cpanel: ignoring dummy byte 0xFF as command\n");
267→		return;
268→	}
269→
270→	m_cmd_buffer[m_cmd_index++] = data;
271→
272→	if (m_cmd_index >= 2)
273→	{
274→		// Full 2-byte command received
275→		process_command();
276→		m_cmd_index = 0;
277→	}
278→}
279→
280→void kn5000_cpanel_device::process_command()
281→{
282→	uint8_t cmd = m_cmd_buffer[0];
283→	uint8_t param = m_cmd_buffer[1];
284→
285→	// Panel selection: bits 7-5 >= 4 means right panel
286→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
287→
288→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
289→		cmd, param, is_right_panel ? "right" : "left");
290→
291→	switch (cmd)
292→	{
293→	// Initialization commands
294→	case 0x1f:  // Init sequence (left)
295→	case 0x1d:
296→	case 0x1e:
297→	case 0xdd:  // Setup mode
298→		LOGMASKED(LOG_COMMANDS, "Init command\n");
299→		send_sync_packet();
300→		m_initialized = true;
301→		break;
302→
303→	// Query commands
304→	case 0x20:  // Query left panel
305→	case 0xe0:  // Query right panel
306→		if (param == 0x00)
307→		{
308→			// Ping - respond with sync
309→			send_sync_packet();
310→		}
311→		else if (param <= 0x0a)
312→		{
313→			// Button segment query
314→			send_button_packet(param, !is_right_panel);
315→		}
316→		else if (param == 0x0b || param == 0x10)
317→		{
318→			// Status query
319→			send_sync_packet();
320→		}
321→		break;
322→
323→	case 0x25:  // Left panel data command
324→	case 0xe2:  // Right panel query
325→	case 0xe3:  // Right panel extended query
326→		send_sync_packet();
327→		break;
328→
329→	case 0x2b:  // Init button state array (left)
330→		send_all_button_states(true);
331→		break;
332→
333→	case 0xeb:  // Init button state array (right)
334→		send_all_button_states(false);
335→		break;
336→
337→	// LED control commands - right panel
338→	case 0x00:
339→	case 0x01:
340→	case 0x02:
341→	case 0x03:
342→	case 0x04:
343→	case 0x08:
344→	case 0x0a:
345→	case 0x0b:
346→	case 0x0c:
347→		process_led_command(cmd, param);
348→		send_sync_packet();
349→		break;
350→
351→	// LED control commands - left panel
352→	case 0xc0:
353→	case 0xc1:
354→	case 0xc2:
355→	case 0xc3:
356→	case 0xc4:
357→	case 0xc8:
358→		process_led_command(cmd, param);
359→		send_sync_packet();
360→		break;
361→
362→	default:
363→		// Unknown command - send sync as acknowledgment
364→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
365→		send_sync_packet();
366→		break;
367→	}
368→}
369→
370→void kn5000_cpanel_device::send_sync_packet()
371→{
372→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
373→	send_byte(0x18);
374→	send_byte(0x00);
375→}
376→
377→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
378→{
379→	if (segment < 0 || segment > 10)
380→		return 0;
381→
382→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
383→	if (port)
384→	{
385→		return port->read() & 0xff;
386→	}
387→	return 0;
388→}
389→
390→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
391→{
392→	// Button packet format:
393→	// Byte 0: [ Panel | Type | Segment ]
394→	//   - Bit 6: Panel select (0=right, 1=left)
395→	//   - Bits 5-3: Type 0 or 1 (button packet)
396→	//   - Bits 3-0 + bit 6: Segment index
397→	// Byte 1: Button state bitmap
398→
399→	uint8_t state = read_button_segment(segment, is_left_panel);
400→
401→	// For button packets, bit 6 indicates left panel
402→	uint8_t header = (segment & 0x0f);
403→	if (is_left_panel)
404→		header |= 0x40;  // Set bit 6 for left panel
405→
406→	// Type 0 for buttons (bits 5-3 = 000)
407→	send_byte(header);
408→	send_byte(state);
409→
410→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
411→		segment, is_left_panel, state);
412→
413→	// Track state for change detection
414→	int state_idx = is_left_panel ? (segment + 11) : segment;
415→	m_last_button_state[state_idx] = state;
416→}
417→
418→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
419→{
420→	// Send all 11 segments for the requested panel
421→	for (int seg = 0; seg <= 10; seg++)
422→	{
423→		send_button_packet(seg, is_left_panel);
424→	}
425→}
426→
427→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
428→{
429→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
430→
431→	switch (row)
432→	{
433→	// Right panel LED rows
434→	case 0x00:
435→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
436→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
437→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
438→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
439→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
440→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
441→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
442→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
443→		break;
444→
445→	case 0x01:
446→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
447→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
448→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
449→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
450→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
451→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
452→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
453→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
454→		break;
455→
456→	case 0x02:
457→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
458→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
459→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
460→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
461→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
462→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
463→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
464→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
465→		break;
466→
467→	case 0x03:
468→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
469→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
470→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
471→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
472→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
473→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
474→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
475→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
476→		break;
477→
478→	case 0x04:
479→		m_cpr_leds[33] = BIT(data, 0);  // D133 - PART SELECT: LEFT
480→		m_cpr_leds[34] = BIT(data, 1);  // D134 - PART SELECT: RIGHT 2
481→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
482→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
483→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
484→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
485→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
486→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
487→		break;
488→
489→	case 0x08:
490→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
491→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
492→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
493→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
494→		break;
495→
496→	case 0x0a:
497→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
498→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
499→		break;
500→
501→	case 0x0b:
502→		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
503→		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
504→		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
505→		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
506→		break;
507→
508→	case 0x0c:
509→		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
510→		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
511→		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
512→		m_cpr_leds[68] = BIT(data, 3);  // D168 - START/STOP 4 BEAT
513→		break;
514→
515→	// Left panel LED rows
516→	case 0xc0:
517→		m_cpl_leds[1] = BIT(data, 0);  // D101 - COMPOSER: MEMORY
518→		m_cpl_leds[2] = BIT(data, 1);  // D102 - COMPOSER: MENU
519→		m_cpl_leds[3] = BIT(data, 2);  // D103 - SOUND ARRANGER: SET
520→		m_cpl_leds[4] = BIT(data, 3);  // D104 - SOUND ARRANGER: ON/OFF
521→		m_cpl_leds[5] = BIT(data, 4);  // D105 - MUSIC STYLIST
522→		m_cpl_leds[6] = BIT(data, 5);  // D106 - FADE IN
523→		m_cpl_leds[7] = BIT(data, 6);  // D107 - FADE OUT
524→		m_cpl_leds[8] = BIT(data, 7);  // D108 - DISPLAY HOLD
525→		break;
526→
527→	case 0xc1:
528→		m_cpl_leds[9] = BIT(data, 0);   // D109 - U.S. TRAD
529→		m_cpl_leds[10] = BIT(data, 1);  // D110 - COUNTRY
530→		m_cpl_leds[11] = BIT(data, 2);  // D111 - LATIN
531→		m_cpl_leds[12] = BIT(data, 3);  // D112 - MARCH & WALTZ
532→		m_cpl_leds[13] = BIT(data, 4);  // D113 - PARTY TIME
533→		m_cpl_leds[14] = BIT(data, 5);  // D114 - SHOW TIME & TRAD DANCE
534→		m_cpl_leds[15] = BIT(data, 6);  // D115 - WORLD
535→		m_cpl_leds[16] = BIT(data, 7);  // D116 - CUSTOM
536→		break;
537→
538→	case 0xc2:
539→		m_cpl_leds[17] = BIT(data, 0);  // D117 - STANDARD ROCK
540→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
541→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
542→		m_cpl_leds[20] = BIT(data, 3);  // D120 - FUNK & FUSION
543→		m_cpl_leds[21] = BIT(data, 4);  // D121 - SOUL & MODERN DANCE
544→		m_cpl_leds[22] = BIT(data, 5);  // D122 - BIG BAND & SWING
545→		m_cpl_leds[23] = BIT(data, 6);  // D123 - JAZZ COMBO
546→		m_cpl_leds[24] = BIT(data, 7);  // D124 - MANUAL SEQUENCE PADS: MENU
547→		break;
548→
549→	case 0xc3:
550→		m_cpl_leds[25] = BIT(data, 0);  // D125 - VARIATION & MSA 1
551→		m_cpl_leds[26] = BIT(data, 1);  // D126 - VARIATION & MSA 2
552→		m_cpl_leds[27] = BIT(data, 2);  // D127 - VARIATION & MSA 3
553→		m_cpl_leds[28] = BIT(data, 3);  // D128 - VARIATION & MSA 4
554→		m_cpl_leds[29] = BIT(data, 4);  // D129 - MUSIC STYLE ARRANGER
555→		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
556→		break;
557→
558→	case 0xc4:
559→		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
560→		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
561→		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
562→		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
563→		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
564→		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
565→		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
566→		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
567→		break;
568→
569→	case 0xc8:
570→		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
571→		break;
572→	}
573→}
