118→{
119→	m_rxd = state;
120→}
121→
122→void kn5000_cpanel_device::tx_start(int state)
123→{
124→	// Called when CPU starts transmitting a new byte - reset RX to sync byte boundaries
125→	if (state)
126→	{
127→		LOGMASKED(LOG_SERIAL, "cpanel tx_start: resetting RX counter for sync\n");
128→		m_rx_clock_count = 8;
129→		m_rx_shift_register = 0;
130→	}
131→}
132→
133→void kn5000_cpanel_device::sioclk(int state)
134→{
135→	if (m_sioclk_state == state)
136→		return;
137→
138→	m_sioclk_state = state;
139→
140→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
141→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
142→
143→	if (state)
144→	{
145→		// Rising edge: Sample RXD (receive bit from CPU)
146→		if (m_rx_clock_count > 0)
147→		{
148→			m_rx_shift_register >>= 1;
149→			m_rx_shift_register |= (m_rxd << 7);
150→			m_rx_clock_count--;
151→
152→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
153→				m_rxd, m_rx_shift_register, m_rx_clock_count);
154→
155→			if (m_rx_clock_count == 0)
156→			{
157→				// Full byte received
158→				m_rx_clock_count = 8;
159→				process_received_byte(m_rx_shift_register);
160→			}
161→		}
162→	}
163→	else
164→	{
165→		// Falling edge: Output TXD (transmit bit to CPU)
166→		// This prepares the bit for the CPU to sample on the next rising edge
167→		if (m_tx_skip_first_falling)
168→		{
169→			// Skip this falling edge - bit 0 was pre-output and we need to give
170→			// CPU a rising edge to sample it before we output bit 1
171→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
172→			m_tx_skip_first_falling = false;
173→		}
174→		else if (m_tx_clock_count > 0)
175→		{
176→			if (m_tx_clock_count == 8)
177→			{
178→				// First bit of a chained byte (loaded from queue) — output bit 0 without shifting
179→				LOGMASKED(LOG_SERIAL, "cpanel TX bit 0 (chained): %d, shift_reg=%02X\n",
180→					m_tx_shift_register & 1, m_tx_shift_register);
181→				m_txd_cb(m_tx_shift_register & 1);
182→				m_tx_clock_count--;
183→			}
184→			else
185→			{
186→				// Normal operation: shift out the next bit
187→				m_tx_shift_register >>= 1;
188→				LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
189→					m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
190→				m_txd_cb(m_tx_shift_register & 1);
191→				m_tx_clock_count--;
192→			}
193→
194→			if (m_tx_clock_count == 0)
195→			{
196→				// Byte sent, check for more
197→				if (!m_tx_queue.empty())
198→				{
199→					m_tx_shift_register = m_tx_queue.front();
200→					m_tx_queue.pop();
201→					m_tx_clock_count = 8;  // Full 8 bits — don't pre-output yet
202→
203→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte queued: %02X (no pre-output)\n",
204→						m_tx_shift_register);
205→
206→					// Don't pre-output: bit 7 of previous byte is still on the line
207→					// and needs to be sampled by CPU on the next rising edge.
208→					// Bit 0 of new byte will be output on the next falling edge.
209→				}
210→				else
211→				{
212→					// Transmission complete — leave the last bit on the line.
213→					// Do NOT call m_txd_cb(1) here: that would overwrite bit 7
214→					// of the last byte before the CPU samples it on the next
215→					// rising edge. The line will be updated when send_byte()
216→					// pre-outputs the next byte's bit 0.
217→					LOGMASKED(LOG_SERIAL, "cpanel TX done, holding last bit\n");
218→				}
219→			}
220→		}
221→	}
222→}
223→
224→void kn5000_cpanel_device::send_byte(uint8_t data)
225→{
226→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
227→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
228→
229→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
230→	{
231→		// Start sending immediately
232→		m_tx_shift_register = data;
233→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
234→
235→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
236→		m_txd_cb(m_tx_shift_register & 1);
237→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
238→			data, data & 1);
239→
240→		// Only skip the first falling edge if clock is currently HIGH.
241→		// If clock is HIGH: next edge = falling (skip it)
242→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
243→		m_tx_skip_first_falling = (m_sioclk_state == 1);
244→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
245→	}
246→	else
247→	{
248→		// Queue for later
249→		m_tx_queue.push(data);
250→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
251→	}
252→}
253→
254→void kn5000_cpanel_device::process_received_byte(uint8_t data)
255→{
256→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
257→
258→	// Ignore 0xFF when it appears as a command byte (first byte of pair).
259→	// In synchronous serial mode, the CPU must send dummy bytes to clock in
260→	// response data. These dummy 0xFF bytes are not valid commands — without
261→	// this filter they would be paired with the next real command byte,
262→	// misaligning the 2-byte command parser and potentially triggering
263→	// unintended LED commands or sync responses.
264→	if (m_cmd_index == 0 && data == 0xFF)
265→	{
266→		LOGMASKED(LOG_SERIAL, "cpanel: ignoring dummy byte 0xFF as command\n");
267→		return;
268→	}
269→
270→	m_cmd_buffer[m_cmd_index++] = data;
271→
272→	if (m_cmd_index >= 2)
273→	{
274→		// Full 2-byte command received
275→		process_command();
276→		m_cmd_index = 0;
277→	}
278→}
279→
280→void kn5000_cpanel_device::process_command()
281→{
282→	uint8_t cmd = m_cmd_buffer[0];
283→	uint8_t param = m_cmd_buffer[1];
284→
285→	// Panel selection: bits 7-5 >= 4 means right panel
286→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
287→
288→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
289→		cmd, param, is_right_panel ? "right" : "left");
290→
291→	switch (cmd)
292→	{
293→	// Initialization commands
294→	case 0x1f:  // Init sequence (left)
295→	case 0x1d:
296→	case 0x1e:
297→	case 0xdd:  // Setup mode
298→		LOGMASKED(LOG_COMMANDS, "Init command\n");
299→		send_sync_packet();
300→		m_initialized = true;
301→		break;
302→
303→	// Query commands
304→	case 0x20:  // Query left panel
305→	case 0xe0:  // Query right panel
306→		if (param == 0x00)
307→		{
308→			// Ping - respond with sync
309→			send_sync_packet();
310→		}
311→		else if (param <= 0x0a)
312→		{
313→			// Button segment query
314→			send_button_packet(param, !is_right_panel);
315→		}
316→		else if (param == 0x0b || param == 0x10)
317→		{
318→			// Status query
319→			send_sync_packet();
320→		}
321→		break;
322→
323→	case 0x25:  // Left panel data command
324→	case 0xe2:  // Right panel query
325→	case 0xe3:  // Right panel extended query
326→		send_sync_packet();
327→		break;
328→
329→	case 0x2b:  // Init button state array (left)
330→		send_all_button_states(true);
331→		break;
332→
333→	case 0xeb:  // Init button state array (right)
334→		send_all_button_states(false);
335→		break;
336→
337→	// LED control commands - right panel
338→	case 0x00:
339→	case 0x01:
340→	case 0x02:
341→	case 0x03:
342→	case 0x04:
343→	case 0x08:
344→	case 0x0a:
345→	case 0x0b:
346→	case 0x0c:
347→		process_led_command(cmd, param);
348→		send_sync_packet();
349→		break;
350→
351→	// LED control commands - left panel
352→	case 0xc0:
353→	case 0xc1:
354→	case 0xc2:
355→	case 0xc3:
356→	case 0xc4:
357→	case 0xc8:
358→		process_led_command(cmd, param);
359→		send_sync_packet();
360→		break;
361→
362→	default:
363→		// Unknown command - send sync as acknowledgment
364→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
365→		send_sync_packet();
366→		break;
367→	}
368→}
369→
370→void kn5000_cpanel_device::send_sync_packet()
371→{
372→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
373→	send_byte(0x18);
374→	send_byte(0x00);
375→}
376→
377→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
378→{
379→	if (segment < 0 || segment > 10)
380→		return 0;
381→
382→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
383→	if (port)
384→	{
385→		return port->read() & 0xff;
386→	}
387→	return 0;
388→}
389→
390→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
391→{
392→	// Button packet format:
393→	// Byte 0: [ Panel | Type | Segment ]
394→	//   - Bit 6: Panel select (0=right, 1=left)
395→	//   - Bits 5-3: Type 0 or 1 (button packet)
396→	//   - Bits 3-0 + bit 6: Segment index
397→	// Byte 1: Button state bitmap
398→
399→	uint8_t state = read_button_segment(segment, is_left_panel);
400→
401→	// For button packets, bit 6 indicates left panel
402→	uint8_t header = (segment & 0x0f);
403→	if (is_left_panel)
404→		header |= 0x40;  // Set bit 6 for left panel
405→
406→	// Type 0 for buttons (bits 5-3 = 000)
407→	send_byte(header);
408→	send_byte(state);
409→
410→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
411→		segment, is_left_panel, state);
412→
413→	// Track state for change detection
414→	int state_idx = is_left_panel ? (segment + 11) : segment;
415→	m_last_button_state[state_idx] = state;
416→}
417→
418→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
419→{
420→	// Send all 11 segments for the requested panel
421→	for (int seg = 0; seg <= 10; seg++)
422→	{
423→		send_button_packet(seg, is_left_panel);
424→	}
425→}
