431→	switch (row)
432→	{
433→	// Right panel LED rows
434→	case 0x00:
435→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
436→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
437→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
